# Filter voice messages to day before yesterday and likely splitwise invitations
filtered = []
for vm in all_msgs:
    sent_at = vm.get('sent_at')
    if not sent_at:
        continue
    try:
        dt = datetime.fromisoformat(sent_at)
    except Exception:
        try:
            dt = datetime.strptime(sent_at, '%Y-%m-%dT%H:%M:%S')
        except Exception:
            continue
    if dt.date().isoformat() != target_date_str:
        continue
    msg_text = (vm.get('message') or '')
    if 'splitwise' not in msg_text.lower():
        continue
    filtered.append(vm)

print('voice_msgs_day_before_yday_total', sum(1 for vm in all_msgs if vm.get('sent_at','').startswith(target_date_str)))
print('splitwise_voice_msgs_day_before_yday', len(filtered))
print('sample_filtered', filtered[:5])

# Extract potential invitation codes from message text
code_regexes = [
    re.compile(r'code\s*(?:=>)?\s*([A-Za-z0-9]+)', re.IGNORECASE),
    re.compile(r'invitation\s*code\s*[:=]\s*([A-Za-z0-9]+)', re.IGNORECASE),
    re.compile(r'code\s*\d*\s*[:=]\s*([A-Za-z0-9]+)', re.IGNORECASE),
]

def extract_code(text):
    for rgx in code_regexes:
        m = rgx.search(text)
        if m:
            return m.group(1)
    # fallback: find all short alnum tokens
    tokens = re.findall(r'\b[A-Za-z0-9]{4,}\b', text)
    return tokens[-1] if tokens else None

for vm in filtered[:10]:
